def P_mod_11(n):
    product = 1
    for k in range(n, n + 38):
        s_k = S(k)
        # We only care if S(k) is a multiple of 11, as the product P(n) is zero mod 11 iff any factor is.
        if s_k % 11 == 0:
            return 0 # Product is a multiple of 11
        product = (product * s_k) % 11
    return product

