def find_max_streak(N_limit):
    max_streak = 0
    current_streak = 0

    for k in range(1, N_limit + 1):
        if S(k) % 11 != 0:
            current_streak += 1
        else:
            max_streak = max(max_streak, current_streak)
            current_streak = 0

    max_streak = max(max_streak, current_streak)
    return max_streak

