def S(n):
    """Calculates the sum of the digits of n."""
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

def check_n(n):
    """Checks if P(n) = S(n)S(n+1)...S(n+37) is NOT a multiple of 11."""
    # P(n) is NOT a multiple of 11 if and only if NONE of the factors S(n+i) is a multiple of 11.
    for i in range(38):
        k = n + i
        if S(k) % 11 == 0:
            return False  # Product IS a multiple of 11
    return True  # Product is NOT a multiple of 11

